mapper.select:
select bidding_platform.*, enter.country_id as countryId, enter.address as address, enter.country_name as countryName, enter.province_id as provinceId, enter.province_name as provinceName, enter.city_id as cityId, enter.city_name as cityName, enter.region_id as regionId, enter.region_name as regionName, bidding_platform.attachment_ids as attachmentIdsList, enter.business_name as crmEnterPriseWarehousingName, project.project_name as crmprojectInformationWarehousingName, enter.business_phone as businessPhone, user_a.name as createUserName,
bidding_platform.create_time as createDateTime,
bidding_platform.informant_date_time as createDateTime,
user_b.name as informantUserName from crm_bidding_platform_warehousing as bidding_platform left join crm_enterprise_warehousing as enter on bidding_platform.crm_enterprise_warehousing_id = enter.id and enter.bool_delete_enum = 0 left join crm_project_information_warehousing as project on project.id = bidding_platform.crm_project_information_warehousing_id and project.bool_delete_enum = 0 left join sys_user as user_a on user_a.id = bidding_platform.create_user_id and user_a.bool_delete_enum = 0 left join sys_user as user_b on user_b.id = bidding_platform.informant_user_id and user_b.bool_delete_enum = 0 left join crm_basics_config as basics_config_a on enter.unit_property_allocation_config_id = basics_config_a.id and basics_config_a.bool_delete_enum = 0 left join crm_basics_config as basics_config_b on enter.unit_class_configuration_id = basics_config_b.id and basics_config_b.bool_delete_enum = 0 left join crm_basics_config as basics_config_c on enter.unit_reputation_allocation_config_id = basics_config_c.id and basics_config_c.bool_delete_enum = 0 left join crm_basics_config as basics_config_d on enter.industry_configuration_id = basics_config_d.id and basics_config_d.bool_delete_enum = 0
bidding_platform.bool_delete_enum = 0
and bidding_platform.crm_check_status_enum = #{crmCheckStatusEnum}
and bidding_platform.crm_record_type_enum = #{checkRecord}
and DATE_FORMAT(bidding_platform.create_time, '%Y-%m-%d') >= #{startDate}
and DATE_FORMAT(bidding_platform.create_time, '%Y-%m-%d') <= #{endDate}
and DATE_FORMAT(bidding_platform.informant_date_time, '%Y-%m-%d') >= #{startDate}
and DATE_FORMAT(bidding_platform.informant_date_time, '%Y-%m-%d') <= #{endDate}
and bidding_platform.country_id = #{countryId}
and bidding_platform.province_id = #{provinceId}
and bidding_platform.city_id = #{cityId}
and bidding_platform.region_id = #{regionId}
and basics_config_a.id = #{unitPropertyAllocationConfigId}
and basics_config_b.id = #{unitClassConfigurationId}
and basics_config_c.id = #{unitReputationAllocationConfigId}
and basics_config_d.id = #{industryConfigurationId}
and bidding_platform.bidding_platform_name like concat('%',#{biddingPlatformName},'%')
and user_b.user_name like concat('%',#{informantUserName},'%')
order by bidding_platform.create_time desc
order by bidding_platform.informant_date_time desc
